hunks.new_code:
float t = dht.readTemperature();

if (isnan(t)) {
  Serial.println("[ERROR] SENSOR_FAIL");
  fanOn = true;
} else if (t >= 60.0) {
  Serial.println("[ALARM] OVERHEAT");
  fanOn = true;
} else if (!fanOn && t >= 30.0) {
  fanOn = true;
} else if (fanOn && t <= 28.0) {
  fanOn = false;
}
